func (m *MockLAN) AddIfNew(ip, mac string) {
	m.Lock()
	defer m.Unlock()

	if _, exists := m.hosts[mac]; !exists {
		m.hosts[mac] = &network.Endpoint{
			IpAddress: ip,
			HwAddress: mac,
			FirstSeen: time.Now(),
			LastSeen:  time.Now(),
		}
		m.addedHosts = append(m.addedHosts, mac)
	}
