func TestRunDiff(t *testing.T) {
	// Test the basic diff functionality with a simpler approach
	tests := []struct {
		name            string
		initialHosts    map[string]string // IP -> MAC
		arpTable        network.ArpTable
		expectedAdded   []string
		expectedRemoved []string
