				"192.168.1.20": "bb:bb:bb:bb:bb:bb",
			},
			expectedAdded:   []string{},
			expectedRemoved: []string{},
		},
		{
			name: "new host discovered",
			initialHosts: map[string]string{
				"192.168.1.10": "aa:aa:aa:aa:aa:aa",
			},
			arpTable: network.ArpTable{
				"192.168.1.10": "aa:aa:aa:aa:aa:aa",
				"192.168.1.20": "bb:bb:bb:bb:bb:bb",
			},
