func NewTicker(s *session.Session) *Ticker {
	mod := &Ticker{
		SessionModule: session.NewSessionModule("ticker", s),
		named:         make(map[string]*Params),
	}

	mod.AddParam(session.NewStringParameter("ticker.commands",
