func stateInt(t *testing.T, mod *Assessment, key string) int {
	t.Helper()
	value, found := mod.State.Load(key)
	if !found {
		t.Fatalf("state key %q not found", key)
	}
	number, ok := value.(int)
	if !ok {
		t.Fatalf("state key %q has type %T", key, value)
	}
	return number
}

