		if port.Port <= 0 || port.Port > 65535 {
			return
		}
		if port.Proto == "" {
			port.Proto = "tcp"
		}
		if port.Service == "" {
			port.Service = network.GetServiceByPort(port.Port, port.Proto)
		}
		ports = append(ports, port)
	}

	switch value := host.Meta.Get("ports").(type) {
	case map[int]*syn_scan.OpenPort:
		for port, info := range value {
			if info == nil {
				add(OpenPort{}, port)
			} else {
				add(OpenPort{
					Port:    info.Port,
					Proto:   info.Proto,
					Service: info.Service,
					Banner:  info.Banner,
				}, port)
			}
		}
	case map[int]syn_scan.OpenPort:
		for port, info := range value {
			add(OpenPort{
				Port:    info.Port,
				Proto:   info.Proto,
				Service: info.Service,
				Banner:  info.Banner,
			}, port)
		}
	case map[int]interface{}:
		for port, entry := range value {
			switch info := entry.(type) {
			case *syn_scan.OpenPort:
				if info == nil {
					add(OpenPort{}, port)
				} else {
					add(OpenPort{
						Port:    info.Port,
						Proto:   info.Proto,
						Service: info.Service,
						Banner:  info.Banner,
					}, port)
				}
			case syn_scan.OpenPort:
				add(OpenPort{
					Port:    info.Port,
					Proto:   info.Proto,
					Service: info.Service,
					Banner:  info.Banner,
				}, port)
			case OpenPort:
				add(info, port)
			default:
				add(OpenPort{}, port)
			}
		}
	case []*syn_scan.OpenPort:
		for _, info := range value {
			if info != nil {
				add(OpenPort{
					Port:    info.Port,
					Proto:   info.Proto,
					Service: info.Service,
					Banner:  info.Banner,
				}, 0)
			}
		}
	case []syn_scan.OpenPort:
		for _, info := range value {
			add(OpenPort{
				Port:    info.Port,
				Proto:   info.Proto,
				Service: info.Service,
				Banner:  info.Banner,
			}, 0)
		}
	case []OpenPort:
		for _, info := range value {
			add(info, 0)
		}
	case []int:
		for _, port := range value {
			add(OpenPort{}, port)
		}
	}

	byPort := make(map[int]OpenPort)
	for _, port := range ports {
		current, found := byPort[port.Port]
		if !found || (current.Banner == "" && port.Banner != "") {
			byPort[port.Port] = port
		}
	}

	ports = ports[:0]
	for _, port := range byPort {
		ports = append(ports, port)
	}
	sort.Slice(ports, func(i, j int) bool {
		return ports[i].Port < ports[j].Port
	})
	return ports
}

